int main(void){SpriteAsset89 a;SpriteVerbs89 v;sa89_id aid,p;const char json[]="{\"frames\":[{\"filename\":\"hero 0\",\"frame\":{\"x\":0,\"y\":0,\"w\":16,\"h\":16},\"duration\":80},{\"filename\":\"hero 1\",\"frame\":{\"x\":16,\"y\":0,\"w\":16,\"h\":16},\"duration\":120}],\"meta\":{\"image\":\"hero.png\",\"frameTags\":[{\"name\":\"run\",\"from\":0,\"to\":1,\"direction\":\"pingpong\"}]}}";sa89_init(&a);if(!sv89_aseprite_import_json(&a,"hero",0,json,(unsigned int)(sizeof(json)-1U),&aid))return 2;if(sa89_find_clip(&a,aid,"run")==SA89_INVALID_ID)return 3;sv89_init(&v,&a);if(!sv89_execute(&v,"player","sprite_play","hero:run"))return 4;p=sv89_target_player(&v,"player");if(p==SA89_INVALID_ID||!a.players[p].playing)return 5;sa89_player_step(&a,p,90U);if(a.players[p].frame_pos!=1U)return 6;if(!sv89_execute(&v,"player","image_speed","0.5"))return 7;if(a.players[p].speed_q16!=32768)return 8;if(!sv89_execute(&v,"player","sprite_flip_x",0))return 9;if(!(a.players[p].draw_flags&SA89_DRAW_FLIP_X))return 10;printf("SpriteVerbs89 PASS asset=%u clips=%u\n",(unsigned)aid,(unsigned)a.clip_count);return 0;}
